export const serviceById = Object.fromEntries(serviceDefinitions.map((service) => [service.id, service])) as Record<ServiceId, ServiceDefinition>;

export function isServiceId(value: string): value is ServiceId {
  return serviceIds.includes(value as ServiceId);
}

export function isLegacyServiceId(value: string): value is LegacyServiceId {
  return Object.prototype.hasOwnProperty.call(legacyServiceRedirects, value);
}

export function contactServiceId(value: string): ServiceId | null {
  if (isServiceId(value)) return value;
  if (isLegacyServiceId(value)) return legacyServiceRedirects[value];
  return null;
}

