function consolidatedGroups(id: ServiceId, locale: Locale) {
  const titles = groupTitles[locale];
  if (id === 'pc-laptop') return [...pcLaptopGroups[locale], { title: titles.pcData, items: localized[locale]['data-backup'][3].slice(0, 7) }];
  if (id === 'websites') {
    const items = localized[locale].websites[3];
    return titles.web.map((title, index) => ({ title, items: index === 0 ? items.slice(2, 5) : index === 1 ? items.slice(1, 2) : index === 2 ? items.slice(5, 8) : index === 3 ? items.slice(7, 9) : items.slice(8, 10) }));
  }
  const sources = ['business-it', 'network-wifi', 'data-backup', 'google-business', 'business-photography', 'digital-design'];
  return titles.business.map((title, index) => ({ title, items: localized[locale][sources[index]][3].slice(0, index < 3 ? 7 : 6) }));
}

export function serviceCopy(id: ServiceId, locale: string): ServiceCopy {
  const selectedLocale = Object.prototype.hasOwnProperty.call(pcLaptopGroups, locale) ? locale as Locale : 'en';
  const copy = consolidatedCopy[selectedLocale][id];
  const groups = consolidatedGroups(id, selectedLocale);
  return { ...copy, intro: [copy.intro], examples: groups.flatMap((group) => group.items), groups, metaTitle: copy.title, metaDescription: copy.short };
}

